        v_v1 = v_in1;
        v_in2 = b2[((17i * (bid / 7i)) + n_r7)];
        v_v2 = v_in2;
        v_v3 = (v_v1 * v_v2);
        v_acc0 = (v_acc0 + v_v3);
    }
    workgroupBarrier();
    s_red[tid] = v_acc0;
    workgroupBarrier();
    if (tid < 16i) {
        v_sv0 = s_red[tid];
        v_sv1 = s_red[(tid + 16i)];
        s_red[tid] = (v_sv0 + v_sv1);
    }
    workgroupBarrier();
    if (tid < 8i) {
        v_sv2 = s_red[tid];
        v_sv3 = s_red[(tid + 8i)];
        s_red[tid] = (v_sv2 + v_sv3);
