        v_sv5 = s_red[(tid + 4i)];
        s_red[tid] = (v_sv4 + v_sv5);
    }
    workgroupBarrier();
    if (tid < 2i) {
        v_sv6 = s_red[tid];
        v_sv7 = s_red[(tid + 2i)];
        s_red[tid] = (v_sv6 + v_sv7);
    }
    workgroupBarrier();
    if (tid < 1i) {
        v_sv8 = s_red[tid];
        v_sv9 = s_red[(tid + 1i)];
        s_red[tid] = (v_sv8 + v_sv9);
    }
    workgroupBarrier();
    v_acc0 = s_red[0i];
    v_v4 = (v_v0 + v_acc0);
    v_v5 = v_v4;
    if (tid == 0i) {
        bout[((bid % 7i) + (7i * (bid / 7i)))] = v_v5;
    }
}

